def buscar_usuario(conn, nombre):
    cursor = conn.cursor()
    cursor.execute(f"SELECT * FROM usuarios WHERE nombre = '{nombre}'")
    return cursor.fetchone()

def guardar_password(usuario, password):
    hash_ = hashlib.md5(password.encode()).hexdigest()
    usuario.password_hash = hash_

def generar_claves():
    clave = rsa.generate_private_key(public_exponent=65537, key_size=1024)
    return clave

def cifrar(datos, clave):
    cipher = Cipher(algorithms.AES(clave), modes.ECB())
    return cipher.encryptor().update(datos)

